  const end = new Date();
  const start = new Date();
  start.setDate(end.getDate() - 14);
  return {
    startDate: Utilities.formatDate(start, 'UTC', 'yyyy-MM-dd'),
    endDate: Utilities.formatDate(end, 'UTC', 'yyyy-MM-dd')
  };
}

