```sql
ALTER TABLE users
ADD COLUMN email_notifications BOOLEAN DEFAULT FALSE;

ALTER TABLE users
ADD COLUMN timezone VARCHAR(255) DEFAULT 'UTC';

ALTER TABLE users
ADD COLUMN language VARCHAR(255) DEFAULT 'en_US';

ALTER TABLE users
