  var metricsData = api.getReportData(viewId, start, end, metrics);

  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  sheet.clearContents();
  sheet.appendRow([
    'Date',
    'Users',
    'Sessions',
    'Bounce Rate',
    'Exit Rate',
    'Average Session Duration'
  ]);

  var date = new Date();
  var start = twoWeeksAgo(date);
  var end = date;

  while (start <= end) {
    metricsData = api.getReportData(viewId, start, end, metrics);
    sheet.appendRow([
      start,
      metricsData.getUsers(),
      metricsData.getSessions(),
      metricsData.getBounceRate(),
      metricsData.getExitRate(),
      metricsData.getAverageSessionDuration()
    ]);
    start.setDate(start.getDate() + 14);
  }
}

// Helper function to get two weeks ago
function twoWeeksAgo(date) {
  var time = new Date(date);
  time.setDate(time.getDate() - 14);
  return time;
}

// Helper function to get GA API instance
function getGAAPIInstance() {
  var api;
  try {
    api = new GoogleApis embedded GA;
  } catch (e) {
    // Handle exception
  }
  return api;
}
```
**Step 3: Update API credentials and Script settings**

1. Create a new API key for your GA account by navigating to `Admin` > `Data Setting > Property > Products` > `Google Analytics API` > `API keys` (Goes by different names)
2. Get the `VIEW ID` for the view containing the metrics you're interested in
3. Update the `spreadsheetId` to match the ID of your Google Sheet
4. Create a new API instance with the `getGAAPIInstance()` function (above is not a complete implementation)

**Step 4: Update Google Sheets setup**

1. Create a new table in your Google Sheet to store the engagement metrics (you may already have one)
2. Update the sheet name and column headers to match your desired format

**Step 5: Set up a trigger**

To automate the script, you'll need to set up a trigger:**

1. In the Apps Script editor, click the `Resources` menu and select `Current project's triggers`.
2. Click the `Create trigger` button.
3. Set the time interval to every 2 weeks (e.g., "2 weeks" > "Days" = 14).

That's it! With these steps, you should now have a script that automatically pulls the engagement metrics from GA4 and updates your Google Sheet every two weeks.

